// #781d1e (23d6b008f36e77a547781d1e) «באג: כפתור החזרה בגיליון ההסכמה של המועמד אינו מגיב».
// При открытом листе согласия «לפני שמתחילים» кнопка «חזרה» (data-testid candidate-back) активна и возвращает на
// «פרטי הלקוח» (שלב 2 מתוך 2), а не на «ברוכים הבאים» (реджект rej_1791930176376); фон под листом inert, кроме «?»
// (помощь доступна до согласия — S-13). Кейсы CALL-022 (касание, iPhone), CALL-023 (мышь + Enter + Space, десктоп),
// CALL-024 (фон неактивен).
// Каждый тест создаёт ОДНОГО кандидата «QA-AUTO-781d1e-…» (business testim, link_only — без письма/SMS); согласие НЕ даётся,
// звонок не начинается (страховка blockCallStarts). Кандидаты не удаляются (правило проекта) → @data, не prod-safe.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { runStamp } from '../support/api';
import { blockCallStarts } from './support';
import { A11Y, newCandidateLink } from './a11y-support';

const HASH = '#781d1e · #23d6b008f36e77a547781d1e';

const sheet = (page: Page) => page.getByTestId('consent-sheet');
const back = (page: Page) => page.getByTestId('candidate-back');
const screen = (page: Page) => page.getByTestId('candidate-screen');

/** Вступление → «איך זה עובד» → «פרטי הלקוח» → «להמשיך» → лист согласия. */
async function openConsent(page: Page, touch: boolean) {
  for (const cta of [A11Y.welcomeCta, A11Y.howCta, A11Y.clientCta]) {
    const b = page.getByRole('button', { name: cta, exact: true });
    await expect(b).toBeVisible({ timeout: 30_000 });
    if (touch) await b.tap();
    else await b.click();
  }
  await expect(sheet(page)).toBeVisible();
  await expect(sheet(page).getByRole('heading', { name: A11Y.consentTitle })).toBeVisible();
}

/** Источник: AC1 «מחזיר למסך הקודם» + реджект: предыдущий экран = «פרטי הלקוח», שלב 2 מתוך 2. */
async function expectClientScreen(page: Page) {
  await expect(sheet(page)).toHaveCount(0);
  await expect(screen(page)).toHaveAttribute('data-step', 'welcome');
  await expect(page.getByRole('heading', { level: 1, name: 'פרטי הלקוח' })).toBeVisible();
  await expect(page.getByText('שלב 2 מתוך 2')).toBeAttached();
  await expect(page.getByRole('button', { name: A11Y.clientCta, exact: true })).toBeVisible();
  await expect(page.getByText('ברוכים הבאים לסימולציית מכירות')).toBeHidden();
}

/** Источник: AC2 «שאר הרקע נשאר לא פעיל»; «חזרה» и «?» вне inert. */
async function expectBackgroundInert(page: Page) {
  const st = await page.evaluate(() => {
    const isInert = (e: Element | null) => !!e?.closest('[inert]');
    const backBtn = document.querySelector('[data-testid="candidate-back"]');
    const helpBtn = Array.from(document.querySelectorAll('button')).find((b) => /פנייה לגורם אנושי/.test(b.textContent || '') && !b.closest('[data-testid="consent-sheet"]'));
    const title = Array.from(document.querySelectorAll('h1')).find((h) => (h.textContent || '').trim() === 'פרטי הלקוח') || null;
    const cont = Array.from(document.querySelectorAll('[data-testid="candidate-screen"] button')).filter(
      (b) => !b.closest('[data-testid="consent-sheet"]') && b !== backBtn && b !== helpBtn && b.getClientRects().length > 0,
    );
    return {
      back: !!backBtn && !isInert(backBtn),
      help: !!helpBtn && !isInert(helpBtn),
      title: isInert(title),
      otherButtons: cont.length,
      otherActive: cont.filter((b) => !isInert(b)).map((b) => (b.textContent || '').trim()),
    };
  });
  expect(st.back, '«חזרה» должна быть активной (не inert)').toBe(true);
  expect(st.help, '«?» помощи должна оставаться активной (S-13: помощь до согласия)').toBe(true);
  expect(st.title, 'заголовок «פרטי הלקוח» под листом должен быть inert').toBe(true);
  expect(st.otherActive, 'активные кнопки фона под листом').toEqual([]);
}

/** Нажатие в точку кнопки фона «להמשיך» (под листом/подложкой) ничего не меняет. */
async function pokeBackground(page: Page, touch: boolean) {
  const cont = page.getByTestId('candidate-continue');
  expect(await cont.count(), 'кнопка фона «להמשיך» (candidate-continue) не найдена под листом').toBe(1);
  const box = await cont.boundingBox();
  if (!box) return; // кнопка не отрисована под листом — нажимать некуда
  const x = box.x + box.width / 2;
  const y = box.y + box.height / 2;
  if (touch) await page.touchscreen.tap(x, y);
  else await page.mouse.click(x, y);
  await expect(sheet(page)).toBeVisible();
  await expect(screen(page)).toHaveAttribute('data-step', 'consent');
}

test.describe(`Лист согласия — кнопка «חזרה» (${HASH})`, () => {
  test(`касание: на листе «לפני שמתחילים» фон inert кроме «חזרה» и «?»; tap «חזרה» → «פרטי הלקוח» (שלב 2 מתוך 2); «להמשיך» снова открывает лист @iphone @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-781d1e-T-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие не дано), не удаляется` });
    const blocked = await blockCallStarts(page);

    await page.goto(link);
    await openConsent(page, true);
    await expect(screen(page)).toHaveAttribute('data-step', 'consent');
    await expectBackgroundInert(page);
    await pokeBackground(page, true);

    await back(page).tap();
    await expectClientScreen(page);

    // С1: лист открывается снова.
    await page.getByRole('button', { name: A11Y.clientCta, exact: true }).tap();
    await expect(sheet(page)).toBeVisible();
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`мышь и клавиатура: «חזרה» на листе согласия — клик, Enter, пробел → каждый раз «פרטי הלקוח» (שלב 2 מתוך 2); Tab не заходит в фон @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-781d1e-K-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие не дано), не удаляется` });
    const blocked = await blockCallStarts(page);

    await page.goto(link);
    await openConsent(page, false);
    await expectBackgroundInert(page);
    await pokeBackground(page, false);

    // Мышь.
    await back(page).click();
    await expectClientScreen(page);

    // Клавиатура: Enter и пробел. До «חזרה» — Shift+Tab из листа; ни одна остановка не внутри inert.
    for (const key of ['Enter', 'Space'] as const) {
      await page.getByRole('button', { name: A11Y.clientCta, exact: true }).click();
      await expect(sheet(page)).toBeVisible();
      const stops: string[] = [];
      for (let i = 0; i < 20; i++) {
        const f = await page.evaluate(() => {
          const e = document.activeElement;
          return { back: e?.getAttribute('data-testid') === 'candidate-back', inert: !!e?.closest('[inert]'), name: (e?.textContent || e?.tagName || '').trim().slice(0, 40) };
        });
        if (f.back) break;
        expect(f.inert, `фокус ушёл в неактивный фон: «${f.name}»`).toBe(false);
        stops.push(f.name);
        await page.keyboard.press('Shift+Tab');
      }
      await expect(back(page), `Shift+Tab не дошёл до «חזרה»: ${stops.join(' → ')}`).toBeFocused();
      await page.keyboard.press(key);
      await expectClientScreen(page);
    }
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
